from scipy.optimize import least_squares
forms={
'logT + eps^n/T':lambda p:p[0]+p[1]*np.log(T)+p[2]*eps**p[3]*T**p[4],
'logT + eps^n exp':lambda p:p[0]+p[1]*np.log(T)+p[2]*eps**p[3]*np.exp(p[4]*T),
'T^m + eps^n T^k':lambda p:p[0]+p[1]*T**p[5]+p[2]*eps**p[3]*T**p[4],
'exp + ..':lambda p:p[0]+p[1]*np.exp(p[5]*T)+p[2]*eps**p[3]*np.exp(p[4]*T),
'1/T + ..':lambda p:p[0]+p[1]/T+p[6]*T+p[2]*eps**p[3]*T**p[4],
}
rng=np.random.default_rng(0)
res={}
for k,f in forms.items():
    best=None
    for i in range(12):
        p0=rng.normal(0,1,7)
        try:
            r=least_squares(lambda p:f(p)-sigma,p0)
            if best is None or r.cost<best.cost:best=r
        except Exception as e: pass
    print(k,2*best.cost/300/np.var(sigma),best.x); res[k]=best
r=forms['logT + eps^n/T'](res['logT + eps^n/T'].x)-sigma
for lo in np.arange(0.2,5,0.6):
    m=(eps>=lo)&(eps<lo+0.6); print(lo, r[m].mean(), r[m].std(), np.corrcoef(r[m],T[m])[0,1])

import itertools
E=eps**3/T; L=np.log(T)
cand={'T':T,'T2':T**2,'T3':T**3,'T4':T**4,'log':L,'1/T':1/T,'1/T2':1/T**2,'TlogT':T*L,'sqrtT':np.sqrt(T),'log2':L**2,'T^1.5':T**1.5,'logT/T':L/T,'T2logT':T*T*L}
out=[]
for k in (1,2,3):
    for s in itertools.combinations(cand,k):
        B=np.c_[[np.ones(300),E]+[cand[n] for n in s]].T
        c=np.linalg.lstsq(B,sigma,rcond=None)[0]
